import manifest from "@/content/previews.json";

/**
 * Short muted preview clips, keyed by Drive file id.
 * Generated by `python scripts/make_previews.py` into public/previews/.
 */
const previews = manifest as Record<string, string>;

export function previewFor(id: string): string | null {
  return previews[id] ?? null;
}

/** Previews are skipped for reduced-motion users and data-saver connections. */
export function previewsAllowed(): boolean {
  if (typeof window === "undefined") return false;
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return false;
  const conn = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  return !conn?.saveData;
}
